#include <stdio.h>
#include <string.h>



int main(void) {
    char s[1002], vowels[1002];
    int n = 0;
    if (!fgets(s, sizeof(s), stdin)) s[0] = '\0';
    for (int i = 0; s[i]; i++) if (strchr("aeiouAEIOU", s[i])) vowels[n++] = s[i];
    vowels[n] = '\0';
    puts(vowels);
    return 0;
}
